import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from pathlib import Path
import json

def fk(q,tool=.2):
    a=[0,0,0,.0825,-.0825,0,.088]
    d=[.333,0,.316,0,.384,0,tool]
    alpha=[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]
    T=np.eye(4)
    for ai,di,al,qi in zip(a,d,alpha,q):
        c,s=np.cos(qi),np.sin(qi);ca,sa=np.cos(al),np.sin(al)
        T=T@np.array([[c,-s,0,ai],[s*ca,c*ca,-sa,-di*sa],[s*sa,c*sa,ca,di*ca],[0,0,0,1]])
    return T

def data():
    out=[]
    for p in sorted(Path('/app/output').glob('[0-9][0-9][0-9]_*/meta.json')):
        m=json.loads(p.read_text());state=np.array(m['proprio']['now'])
        out.append((state[4:11],state[26:29],np.array(m['cameras']['robot0_eye_in_hand']['cam2world_gl'])[:3,:3]))
    return out

def fit():
    dat=data()
    def err(x):
        R=Rotation.from_rotvec(x[:3]).as_matrix();t=x[3:6]
        return np.concatenate([R@fk(q,x[6])[:3,3]+t-p for q,p,cam in dat])
    res=least_squares(err,[0,0,np.pi,3.65,-3.35,.9,.2],max_nfev=1000)
    return res
if __name__=='__main__':
    res=fit();print('fit',res.x,'err',res.fun,'cost',res.cost)
    for q,p,R in data(): print('q',q,'local',fk(q)[:3,3],'world',p)
